-- 0112-r231-attaquer-et-se-defendre : décision R231 du propriétaire (2026-11-08, docs/decisions-regles.md) : réécriture des pages « Attaquer et se défendre » et
-- « Attaque et Défense » et mots-clés de la fiche. Migration de DONNÉES seules (section 1 ; PRAGMA user_version 111 -> 112 ; rien d'autre ne change dans
-- data/schema.sql) ; rien ne va dans historique_modification (la migration n'est pas une modification du site de dev). Registre avant/après :
-- 0112-r231-attaquer-et-se-defendre.json (`textes` : une entrée par texte réécrit, page entière comprise ; `mots_cles_crees`, `mots_cles_colores`, `renvois`, `ecarts`). Textes du cahier de
-- game-design, mot pour mot.
--   * guide/attaquer-et-se-defendre porte toute l'attaque, retitrée « Attaquer » ; guide/attaque-et-defense toute la défense, retitrée « Se défendre »
--     (R231 (1)) ; ids et adresses figés, l'ancien titre en alias. guide/attaque-et-defense n'est plus une copie de source (R199 et R184 (3) amendés
--     pour elle) ; sa provenance (origine docs, source_ref, page_source) ne change pas : tools/db/pages_md.py en recalcule la famille.
--   * Ancres figées posées : #jet-d-attaque, #critiques-en-attaque, #une-arme-dans-chaque-main, #localisation-des-degats (Attaquer) ;
--     #parer-ou-esquiver, #critiques-en-defense, #defenses-par-tour, #defense-impossible, #attaques-de-zone (Se défendre).
--   * 39 mots-clés créés (28 compétences : les 30 moins Parade et Esquive ; 6 caractéristiques ; 5 notions), 2 colorés (Parade, Esquive), 4 modifiés.
-- La garde : chaque UPDATE ne touche que la valeur d'avant (corps entier pour les deux pages, fragment présent une seule fois ailleurs) et doit changer
-- exactement une ligne ; une valeur que le site de dev aurait réécrite arrête la migration. Un mot-clé créé déjà présent l'arrête aussi (clé primaire,
-- libelle_cle UNIQUE).
-- Inchangés : guide/guide-pour-mj-maverick (sommaire copié du Doc), note_version_ligne, historique_modification, page_source, page_tag.

CREATE TEMP TABLE garde_0112 (quoi TEXT NOT NULL, lignes INTEGER NOT NULL, attendu INTEGER NOT NULL DEFAULT 1, CHECK (lignes = attendu));

-- 1. Les deux pages (R231 (1)) : titre (titre_cle = normalize), résumé et corps réécrits en entier ; la garde : la ligne a encore le titre, le
--    résumé et le corps d’avant la migration (une valeur que le site de dev aurait réécrite arrête la migration).
UPDATE page SET titre = 'Attaquer', titre_cle = 'attaquer', resume = 'Le jet d’attaque et la compétence qui le porte, la réussite et l’échec critiques, une arme dans chaque main, les armes à part, les coups visés et les situations qui renforcent une attaque.',
  corps_md = 'Une attaque se joue en deux jets de {{des|D100}} : celui de l’attaquant, qui fait l’objet de cette page, puis, si sa {{posture|posture}} le lui permet, celui de la cible pour se défendre (voir {{attaque-et-defense}}). Si le coup passe, il reste à compter les dégâts (voir {{degats|Les dégâts}}).' || char(10) || '' || char(10) || '## Le jet d’attaque {#jet-d-attaque}' || char(10) || '' || char(10) || 'L’attaquant lance un {{des|D100}} et doit faire son {{score|score}} ou moins dans la {{competence|compétence}} qui sert à l’attaque : c’est son {{jet-dattaque|jet d’attaque}}. Entre parenthèses, la {{caracteristiques|caractéristique}} dont dépend la compétence.' || char(10) || '' || char(10) || '- **avec une arme**, la compétence de l’arme, que donne la colonne *Compétence* de la page des {{armes|armes}} : {{arme-legere}} ({{agilite}}), {{arme-lourde}} ({{force}}), {{arc}} ({{force}}) ou {{arbalete}} ({{perception}}) ; certaines armes en écrivent deux (Lourde / Légère, Arc / Légère) : le joueur choisit alors celle des deux qui sert ;' || char(10) || '- **avec un sort**, la compétence {{magie-competence|Magie}} ({{intelligence}}) ; les {{mage-rouge|mages rouge}}, {{mage-bleu|bleu}} et {{mage-vert|vert}} lancent les leurs avec {{concentration}} ({{volonte}}).' || char(10) || '' || char(10) || 'La posture de l’attaquant joue aussi sur son jet et sur ses dégâts (voir {{posture|Les postures}}).' || char(10) || '' || char(10) || '## Les critiques en attaque {#critiques-en-attaque}' || char(10) || '' || char(10) || 'Deux résultats sortent de l’ordinaire :' || char(10) || '' || char(10) || '- **{{reussite-critique}} (1 à 5)** : les dégâts de l’attaque, bonus compris, sont doublés, et seule une réussite critique de la cible peut alors arrêter le coup, entièrement ou en partie (voir {{attaque-et-defense}}). La {{posture|posture offensive}} l’élargit à 1 à 10 sur les six jets d’attaque, *Concentration* comprise ; d’autres bonus (un score au-delà de 95 %, un don, un sort, la tenaille…) l’élargissent encore, sans jamais dépasser 1 à 15 (voir {{reussir-une-action}}).' || char(10) || '- **{{echec-critique}} (96 à 100)** : la cible bénéficie d’une {{attaque-dopportunite|attaque d’opportunité}}, ou peut désarmer l’attaquant si c’est possible ; le {{maitre-du-jeu|MJ}} peut aussi en décider autrement.' || char(10) || '' || char(10) || '## Une arme dans chaque main {#une-arme-dans-chaque-main}' || char(10) || '' || char(10) || 'Avec une arme de mêlée dans chaque main ({{ambidextrie|ambidextrie}}), chaque attaque subit un malus :' || char(10) || '' || char(10) || '- **−20 %** pour la main directrice (l’arme 1 de la {{fiche-de-personnage|fiche}}), **−40 %** pour la main secondaire ;' || char(10) || '- ce malus est divisé par deux pour la main qui tient une dague, et divisé par deux pour un personnage de la classe {{bimane}} ; les deux se cumulent.' || char(10) || '' || char(10) || '*Exemple : un Bimane qui tient une épée et une dague attaque à −10 % de chaque main.*' || char(10) || '' || char(10) || 'Cela ne vaut que pour deux armes de mêlée : l’arc, l’arbalète, les armes de jet et les bombes n’y entrent pas.' || char(10) || '' || char(10) || '## Quelques armes à part' || char(10) || '' || char(10) || '- **La dague** : un coup réussi à la dague impose un malus de 10 % au {{jet-de-defense|jet de défense}} de l’adversaire (20 % avec la lame secrète).' || char(10) || '- **Les armes de jet** : on peut en lancer deux en sacrifiant son déplacement et son action (ou utiliser deux fois la fronde).' || char(10) || '- **Le {{mordhau}}** : prendre son arme par la lame pour frapper avec le manche donne des dégâts de frappe à une arme qui n’en fait pas, au risque de l’abîmer (voir {{lequipement}}).' || char(10) || '' || char(10) || '## Viser une partie du corps {#localisation-des-degats}' || char(10) || '' || char(10) || 'Viser la tête, un bras ou une jambe plutôt que le corps est plus difficile : chaque zone a son malus pour toucher. En échange, le coup y porte un effet en plus, propre à la zone ; le corps, lui, n’a ni malus ni effet (voir {{localisation-des-degats}}). Une attaque non ciblée touche par défaut le torse, sauf indication contraire du MJ.' || char(10) || '' || char(10) || '| **Zone touchée** | **Malus pour toucher** | **Effet** |' || char(10) || '| :-: | :-: | :-: |' || char(10) || '| **Tête** | -25% | Le coup inflige **+10 {{degats\|dégâts}}** |' || char(10) || '| **Corps** | 0% | Aucun effet |' || char(10) || '| **Bras droit** | -18% | **-15%** au prochain test d’attaque avec une arme |' || char(10) || '| **Bras gauche** | -18% | **-5%** au prochain test (peu importe lequel) |' || char(10) || '| **Jambe droite** | -12% | **-1 {{vitesse\|vitesse}}** au prochain tour |' || char(10) || '| **Jambe gauche** | -12% | **-4 {{initiative\|initiative}}** au prochain tour |' || char(10) || '' || char(10) || '- **Personnage gaucher :** les effets entre bras droit / bras gauche et jambe droite / jambe gauche sont **inversés**.' || char(10) || '- **Humanoïde par défaut :** ce tableau est pensé pour les créatures humanoïdes.' || char(10) || '- **Adaptation pour monstres :** le MJ peut réassigner certaines zones pour coller à l’anatomie de la créature. *Exemple : pour un scorpion, la « tête » correspondait à sa **queue**, et donc le malus et l’effet s’y appliquaient.*' || char(10) || '' || char(10) || '## Les situations qui changent la donne' || char(10) || '' || char(10) || 'Le détail de chacune est dans {{tenaille|La prise en tenaille et zone d’influence}}, {{attaque-dopportunite|Les attaques d''opportunité}}, {{attaque-discrete|Les attaques discrètes}} et {{embuscade|L’embuscade}}.' || char(10) || '' || char(10) || '- **La prise en tenaille.** Un ennemi encerclé au corps à corps par des alliés placés sur des cases opposées (devant et derrière, ou à gauche et à droite) est en tenaille : à deux, +4 aux dégâts ; à trois, encore +4 ; à quatre, en plus, +5 % de réussite critique pour les alliés (jamais au-delà de 1 à 15) et −10 % au jet de défense de la cible. Les effets se cumulent.' || char(10) || '- **L’attaque d’opportunité.** Une attaque offerte quand un adversaire rate son attaque contre vous sur un échec critique, quand il sort de votre {{zone-dinfluence|zone d’influence}} (sauf si c’est vous qui l’y forcez), ou quand un don de votre classe le permet. Une seule par tour et par joueur, sauf don qui en permet plus. Ce doit être une action simple : un coup avec une arme déjà dégainée et à portée, ou un sort d’attaque ; pas de sort qui n’attaque pas, de sort de niveau 5, de déplacement, de potion ni d’arme à dégainer. Pour la défense de sa victime, voir {{attaque-et-defense}}.' || char(10) || '- **L’attaque discrète.** Frapper une cible qui ne vous voit pas venir ajoute un dé aux dégâts (2d6 à la dague deviennent 3d6). Il faut passer en mode discret (trois {{action-rapide|actions rapides}}, deux pour un {{voleur|voleur}}), réussir un jet de {{ruse}}, et qu’aucun ennemi ne vous voie clairement. La cible tente alors un jet d’{{observation}} ou de {{distinction}} : si elle fait mieux que votre jet de discrétion, la discrétion est perdue, et le dé en plus avec elle. À ne pas confondre avec l’attaque sournoise, qui vient d’une classe.' || char(10) || '- **L’embuscade.** Vous consommez l’{{action|action}} de votre tour pour attendre un ennemi, et lui porter une attaque d’opportunité dès qu’il entre dans la zone voulue : à une distance égale à la {{vitesse|vitesse}} divisée par 2 avec une arme de corps à corps (on fonce alors sur lui), à la {{portee|portée}} de l’arme avec une arme à distance, à la portée du sort avec la magie. Posture, déplacement et actions rapides restent possibles pendant ce tour. Ce que peut faire la victime est dans {{attaque-et-defense}}.' || char(10) || ''
  WHERE id = 'guide/attaquer-et-se-defendre' AND titre = 'Attaquer et se défendre' AND resume = 'Le jet d’attaque, la parade et l’esquive, la défense partielle qui divise les dégâts par deux, les coups visés et les situations qui changent la donne.'
  AND corps_md = 'Un coup se joue en deux jets de D100 : celui de l’attaquant pour toucher, puis, si sa posture le lui permet, celui de la cible pour se défendre. Si le coup passe, il reste à compter les dégâts (voir {{degats|Les dégâts}}).' || char(10) || '' || char(10) || '## Attaquer' || char(10) || '' || char(10) || '### Le jet d’attaque' || char(10) || '' || char(10) || 'L’attaquant lance un D100 et doit faire son score ou moins dans la compétence qui sert à l’attaque :' || char(10) || '' || char(10) || '- **avec une arme**, la compétence de l’arme, que donne la colonne *Compétence* de la page des {{armes|armes}} : *Arme Légère* (Agilité), *Arme Lourde* (Force), *Arc* (Force) ou *Arbalète* (Perception) ; certaines armes en écrivent deux (Lourde / Légère, Arc / Légère) : le joueur choisit alors celle des deux qui sert ;' || char(10) || '- **avec un sort**, la compétence *Magie* (Intelligence) ; les mages rouge, bleu et vert lancent les leurs avec *Concentration* (Volonté).' || char(10) || '' || char(10) || 'Deux résultats sortent de l’ordinaire :' || char(10) || '' || char(10) || '- **Réussite critique (1 à 5)** : les dégâts de l’attaque, bonus compris, sont doublés, et la cible ne peut bloquer le coup que par une réussite critique égale ou plus basse que celle de l’attaquant. La posture offensive l’élargit à 1 à 10 sur les six jets d’attaque, *Concentration* comprise ; d’autres bonus (un score au-delà de 95 %, un don, un sort, la tenaille…) l’élargissent encore, sans jamais dépasser 1 à 15 (voir {{reussir-une-action}}).' || char(10) || '- **Échec critique (96 à 100)** : la cible peut riposter par une attaque d’opportunité, ou désarmer l’attaquant si c’est possible ; le MJ peut aussi en décider autrement.' || char(10) || '' || char(10) || '### Une arme dans chaque main' || char(10) || '' || char(10) || 'Avec une arme de mêlée dans chaque main, chaque attaque subit un malus :' || char(10) || '' || char(10) || '- **−20 %** pour la main directrice (l’arme 1 de la fiche), **−40 %** pour la main secondaire ;' || char(10) || '- ce malus est divisé par deux pour la main qui tient une dague, et divisé par deux pour un personnage de la classe {{bimane}} ; les deux se cumulent.' || char(10) || '' || char(10) || '*Exemple : un Bimane qui tient une épée et une dague attaque à −10 % de chaque main.*' || char(10) || '' || char(10) || 'Cela ne vaut que pour deux armes de mêlée : l’arc, l’arbalète, les armes de jet et les bombes n’y entrent pas.' || char(10) || '' || char(10) || '### Quelques armes à part' || char(10) || '' || char(10) || '- **La dague** : un coup réussi à la dague impose un malus de 10 % à la défense de l’adversaire (20 % avec la lame secrète).' || char(10) || '- **Les armes de jet** : on peut en lancer deux en sacrifiant son déplacement et son action (ou utiliser deux fois la fronde).' || char(10) || '- **Le {{mordhau}}** : prendre son arme par la lame pour frapper avec le manche donne des dégâts de frappe à une arme qui n’en fait pas, au risque de l’abîmer (voir {{lequipement}}).' || char(10) || '' || char(10) || '## Se défendre' || char(10) || '' || char(10) || '### Parer ou esquiver' || char(10) || '' || char(10) || 'Attaquée, la cible peut tenter :' || char(10) || '' || char(10) || '- une **parade**, avec son arme ou son bouclier : compétence *Parade* (Force) ;' || char(10) || '- une **esquive** : compétence *Esquive* (Agilité).' || char(10) || '' || char(10) || 'C’est un jet de D100, possible seulement si sa posture le permet et qu’il lui reste des défenses pour le tour. Pour bloquer entièrement le coup, deux conditions : **réussir son jet, et faire un résultat égal ou inférieur à celui de l’attaquant.** Au D100, un meilleur résultat est un résultat plus bas.' || char(10) || '' || char(10) || '*Exemple : l’attaquant touche avec un résultat de 30. La cible réussit sa parade avec un résultat de 25 : 25 est plus bas que 30, le coup est entièrement bloqué.*' || char(10) || '' || char(10) || '| Résultat de la défense | Ce qui se passe |' || char(10) || '| --- | --- |' || char(10) || '| Réussie, avec un résultat égal ou inférieur à celui de l’attaque | Le coup est entièrement bloqué. |' || char(10) || '| Réussie, mais avec un résultat supérieur à celui de l’attaque | **Défense partielle** : les dégâts finaux sont divisés par 2. Si c’est une parade au bouclier, ses AP ou son AM comptent à ce moment-là. |' || char(10) || '| Ratée, même avec un résultat inférieur à celui de l’attaque | La défense échoue : les dégâts sont entiers. |' || char(10) || '' || char(10) || 'Là encore, les critiques changent tout :' || char(10) || '' || char(10) || '- **Réussite critique en défense** : une contre-attaque est possible, ou désarmer l’adversaire ; le MJ peut aussi imaginer autre chose. La posture défensive l’élargit, jamais au-delà de 1 à 15 (voir {{posture|Les postures}}).' || char(10) || '- **Échec critique en défense** : l’AP et l’AM de la cible ne comptent pas, et l’attaquant ajoute +8 à ses dégâts (ou autre chose, au choix du MJ).' || char(10) || '' || char(10) || '### Combien de défenses par tour ?' || char(10) || '' || char(10) || 'Cela dépend de la posture du moment : certaines n’en permettent aucune, d’autres un nombre limité par tour, et la posture défensive les permet sans limite, mais au-delà de deux parades ou esquives, chaque défense y fait baisser la réussite de la suivante. Les chiffres de chaque posture sont dans {{posture|Les postures}}.' || char(10) || '' || char(10) || 'La posture défensive permet aussi l’**intervention** : parer ou esquiver le coup à la place d’un allié adjacent.' || char(10) || '' || char(10) || 'Les boss, pensés pour affronter une équipe de quatre joueurs, ont plus de parades et d’esquives que les autres en posture neutre, de vigilance ou de symbiose (voir {{posture|Les postures}}).' || char(10) || '' || char(10) || '### Les attaques de zone' || char(10) || '' || char(10) || '- Pour esquiver une attaque de zone, il faut en sortir : l’Esquive perd 5 % par case à parcourir, et l’on ne peut pas parcourir plus de cases que sa vitesse. Un personnage qui a 4 de vitesse ne peut donc pas esquiver une zone qui s’étend sur 5 cases ou plus.' || char(10) || '- La parade n’est pas concernée.' || char(10) || '- Quand deux personnages sont pris dans la même zone, l’un ne peut pas protéger l’autre, même en posture défensive.' || char(10) || '' || char(10) || '## Viser une partie du corps' || char(10) || '' || char(10) || 'Viser la tête, un bras ou une jambe plutôt que le corps est plus difficile : chaque zone a son malus pour toucher. En échange, le coup y porte un effet en plus, propre à la zone ; le corps, lui, n’a ni malus ni effet. Le malus et l’effet de chaque zone sont dans le tableau « Localisation des dégâts » de {{attaque-et-defense}}.' || char(10) || '' || char(10) || '- Pour un personnage gaucher, les effets du côté droit et du côté gauche sont inversés.' || char(10) || '- Ce tableau est pensé pour les humanoïdes : face à un monstre, le MJ peut en réattribuer les zones selon son anatomie (pour un scorpion, la « tête » peut être sa queue).' || char(10) || '' || char(10) || '## Les situations qui changent la donne' || char(10) || '' || char(10) || 'Le détail de chacune est dans {{tenaille|La prise en tenaille et zone d’influence}}, {{attaque-dopportunite|Les attaques d''opportunité}}, {{attaque-discrete|Les attaques discrètes}} et {{embuscade|L’embuscade}}.' || char(10) || '' || char(10) || '- **La prise en tenaille.** Un ennemi encerclé au corps à corps par des alliés placés sur des cases opposées (devant et derrière, ou à gauche et à droite) est en tenaille : à deux, +4 aux dégâts ; à trois, encore +4 ; à quatre, en plus, +5 % de réussite critique pour les alliés (jamais au-delà de 1 à 15) et −10 % au jet de défense de la cible. Les effets se cumulent.' || char(10) || '- **L’attaque d’opportunité.** Une attaque offerte quand un adversaire rate son attaque contre vous sur un échec critique, quand il sort de votre zone d’influence (sauf si c’est vous qui l’y forcez), ou quand un don de votre classe le permet. Une seule par tour et par joueur, sauf don qui en permet plus. Ce doit être une action simple : un coup avec une arme déjà dégainée et à portée, ou un sort d’attaque ; pas de sort qui n’attaque pas, de sort de niveau 5, de déplacement, de potion ni d’arme à dégainer. Sa victime ne peut ni parer ni esquiver, sauf en posture défensive.' || char(10) || '- **L’attaque discrète.** Frapper une cible qui ne vous voit pas venir ajoute un dé aux dégâts (2d6 à la dague deviennent 3d6). Il faut passer en mode discret (trois actions rapides, deux pour un {{voleur|voleur}}), réussir un jet de *Ruse*, et qu’aucun ennemi ne vous voie clairement. La cible tente alors un jet d’*Observation* ou de *Distinction* : si elle fait mieux que votre jet de discrétion, la discrétion est perdue, et le dé en plus avec elle. À ne pas confondre avec l’attaque sournoise, qui vient d’une classe.' || char(10) || '- **L’embuscade.** Vous consommez l’action de votre tour pour attendre un ennemi, et lui porter une attaque d’opportunité dès qu’il entre dans la zone voulue : à une distance égale à la vitesse divisée par 2 avec une arme de corps à corps (on fonce alors sur lui), à la portée de l’arme avec une arme à distance, à la portée du sort avec la magie. Posture, déplacement et actions rapides restent possibles pendant ce tour. Contrairement aux autres attaques d’opportunité, la victime d’une embuscade peut parer ou esquiver ; et la posture de vigilance déjoue l’embuscade.' || char(10) || '';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('page guide/attaquer-et-se-defendre : titre, résumé et corps (R231 (1))', changes(), 1);

UPDATE page SET titre = 'Se défendre', titre_cle = 'se-defendre', resume = 'La parade et l’esquive, la défense partielle qui divise les dégâts par deux, les critiques en défense, le nombre de défenses par tour, l’intervention, les attaques qu’on ne peut pas parer et les attaques de zone.',
  corps_md = 'Quand un coup est porté (voir {{attaquer-et-se-defendre}}), la cible peut se défendre si sa {{posture|posture}} le permet et s’il lui reste des défenses pour le tour. Cette page dit comment, et ce qu’il en coûte.' || char(10) || '' || char(10) || '## Parer ou esquiver {#parer-ou-esquiver}' || char(10) || '' || char(10) || 'Attaquée, la cible peut tenter :' || char(10) || '' || char(10) || '- une {{parade|parade}}, avec son arme ou son {{bouclier|bouclier}} : {{competence|compétence}} *Parade* ({{force}}) ;' || char(10) || '- une {{esquive|esquive}} : compétence *Esquive* ({{agilite}}).' || char(10) || '' || char(10) || 'C’est son {{jet-de-defense|jet de défense}}, un {{des|D100}}. Pour bloquer entièrement le coup, deux conditions : **réussir son jet** (faire son {{score|score}} ou moins), **et faire un résultat égal ou inférieur à celui de l’attaquant.** Au D100, un {{meilleur-resultat|meilleur résultat}} est un résultat plus bas.' || char(10) || '' || char(10) || '| Résultat de la défense | Ce qui se passe |' || char(10) || '| --- | --- |' || char(10) || '| Réussie, avec un résultat égal ou inférieur à celui de l’attaque | Le coup est entièrement bloqué. |' || char(10) || '| Réussie, mais avec un résultat supérieur à celui de l’attaque | **{{defense-partielle}}** : les dégâts finaux sont divisés par 2 (voir {{degats\|Les dégâts}}). Si c’est une parade au bouclier, ses {{armure-physique\|AP}} ou son {{armure-magique\|AM}} comptent à ce moment-là. |' || char(10) || '| Ratée, même avec un résultat inférieur à celui de l’attaque | La défense échoue : les dégâts sont entiers. |' || char(10) || '' || char(10) || '*Exemple : l’attaque touche avec un résultat de 42, et la cible a 60 % en Esquive. Sur 42 ou moins, esquive totale ; de 43 à 60, esquive partielle ; sur 61 et plus, l’esquive échoue.*' || char(10) || '' || char(10) || '## Les critiques en défense {#critiques-en-defense}' || char(10) || '' || char(10) || '- **Contre une {{reussite-critique|réussite critique}} de l’attaquant**, seule une réussite critique de la défense compte : un résultat critique égal ou inférieur à celui de l’attaquant bloque entièrement le coup ; un résultat critique supérieur à celui de l’attaquant donne une {{defense-partielle|défense partielle}} ; tout autre résultat est un échec, avec des dégâts entiers, même si le jet est réussi.' || char(10) || '' || char(10) || '  *Exemple : l’attaquant fait une réussite critique sur 3, et la plage de réussite critique de la défense va de 1 à 5. Sur 1, 2 ou 3, le coup est entièrement bloqué ; sur 4 ou 5 (ou plus si sa plage de critique est plus large), défense partielle ; au-delà, la défense échoue.*' || char(10) || '- **Réussite critique en défense** : une contre-attaque est possible (dans la mesure du possible), ou désarmer l’adversaire ; le {{maitre-du-jeu|MJ}} peut aussi imaginer autre chose. La {{posture|posture défensive}} l’élargit, jamais au-delà de 1 à 15 (voir {{posture|Les postures}} et {{reussites-echecs-et-critiques}}).' || char(10) || '- **{{echec-critique}} en défense** : l’{{armure-physique|AP}} et l’{{armure-magique|AM}} de la cible ne comptent pas, et l’attaquant ajoute +8 à ses dégâts (ou autre chose, au choix du MJ).' || char(10) || '' || char(10) || '## Combien de défenses par tour ? {#defenses-par-tour}' || char(10) || '' || char(10) || 'Cela dépend de la posture du moment : certaines n’en permettent aucune, d’autres un nombre limité par tour, et la posture défensive les permet sans limite, mais au-delà de deux parades ou esquives, chaque défense y fait baisser la réussite de la suivante. Les chiffres de chaque posture sont dans {{posture|Les postures}}.' || char(10) || '' || char(10) || 'La posture défensive permet aussi l’{{intervention|intervention}} : parer ou esquiver le coup à la place d’un allié adjacent.' || char(10) || '' || char(10) || 'Les {{boss|boss}}, pensés pour affronter une équipe de quatre joueurs, ont plus de parades et d’esquives que les autres en posture neutre, de vigilance ou de symbiose (voir {{posture|Les postures}}).' || char(10) || '' || char(10) || '## Quand la défense est impossible ou gênée {#defense-impossible}' || char(10) || '' || char(10) || '- **L’{{attaque-dopportunite|attaque d’opportunité}}** : sa victime ne peut ni parer ni esquiver, sauf en posture défensive.' || char(10) || '- **L’{{embuscade|embuscade}}** : contrairement aux autres attaques d’opportunité, sa victime peut parer ou esquiver ; et la posture de vigilance déjoue l’embuscade.' || char(10) || '- **Ce qui gêne la défense** : un coup réussi à la dague (−10 % au jet de défense, −20 % avec la lame secrète) et la {{tenaille|prise en tenaille}} à quatre (−10 % au jet de défense de la cible) ; voir {{attaquer-et-se-defendre}}.' || char(10) || '' || char(10) || '## Les attaques de zone {#attaques-de-zone}' || char(10) || '' || char(10) || '- Pour esquiver une attaque de zone, il faut en sortir : l’{{esquive}} perd 5 % par case à parcourir, et l’on ne peut pas parcourir plus de cases que sa {{la-vitesse-et-la-portee|vitesse}}. Un personnage qui a 4 de vitesse ne peut donc pas esquiver une zone qui s’étend sur 5 cases ou plus.' || char(10) || '- La parade n’est pas concernée.' || char(10) || '- Quand deux personnages sont pris dans la même zone, l’un ne peut pas protéger l’autre, même en posture défensive.' || char(10) || ''
  WHERE id = 'guide/attaque-et-defense' AND titre = 'Attaque et Défense' AND resume = 'Quand une attaque est prodiguée, un jet de D100 est nécessaire pour réussir l''action (il faut faire son score ou moins pour réussir).'
  AND corps_md = '## Attaque' || char(10) || '' || char(10) || 'Quand une attaque est prodiguée, un jet de D100 est nécessaire pour réussir l''action (il faut faire son score ou moins pour réussir).' || char(10) || '' || char(10) || '**Cas particuliers :**' || char(10) || '' || char(10) || 'Lors d''une réussite critique (score au dé = 1 - 5 de base, voir {{reussites-echecs-et-critiques}}), les dégâts de base seront doublés ! La défense doit faire une réussite critique égale ou plus basse pour réussir à bloquer un tel coup.' || char(10) || '' || char(10) || 'Lors d''un échec critique (score au dé = 96 - 100), la cible bénéficie d''une attaque d''opportunité ou bien peut désarmer la cible (si c’est possible), ou autre idée du mj.' || char(10) || '' || char(10) || '## Défense' || char(10) || '' || char(10) || 'Lors d''une parade ou esquive, un jet de D100 est nécessaire pour réussir l''action mais deux conditions doivent être réunies pour bloquer totalement l''attaque : doit réussir son jet de parade ou esquive ET doit faire un résultat égal ou plus bas que celui de l''attaquant !' || char(10) || '' || char(10) || 'Si le test de parade/esquive est réussi mais le score n''est pas meilleur que celui de l''attaquant : les dégâts finaux sont divisés par 2. Si jamais une parade est faite avec un bouclier, les AP ou AM du bouclier s''appliquent à ce moment-là.' || char(10) || '' || char(10) || 'Si le test de parade/esquive est raté malgré un meilleur score, le test est quand même échoué donc dégâts normaux.' || char(10) || '' || char(10) || '**Cas particuliers :**' || char(10) || '' || char(10) || 'Lors d''une réussite critique, une contre-attaque est possible (dans la mesure du possible) ou une autre idée du MJ.' || char(10) || '' || char(10) || 'Lors d''un échec critique, les AP et AM ne sont pas pris en compte dans les dégâts et l''agresseur inflige un bonus de +8 dégâts ou une autre idée du MJ.' || char(10) || '' || char(10) || 'Lors d’une attaque de zone, l’Esquive a un malus de 5% par case parcourue pour échapper à l’attaque, le maximum de cases correspond à {{la-vitesse-et-la-portee|la vitesse}} du personnage (Un personnage à 4 de vitesse ne pourra pas esquiver une zone qui s’étend à 5 cases ou plus). La parade n’est pas concernée.' || char(10) || '' || char(10) || 'Encore par rapport aux attaques de zone, une personne ne peut pas protéger quelqu’un à côté d’elle si les deux sont dans l’attaque de zone, malgré la posture de défense.' || char(10) || '' || char(10) || '## Localisation des dégâts' || char(10) || '' || char(10) || '| **Zone touchée** | **Malus pour toucher** | **Effet** |' || char(10) || '| :-: | :-: | :-: |' || char(10) || '| **Tête** | -25% | Le coup inflige **+10 dégâts** |' || char(10) || '| **Corps** | 0% | Aucun effet |' || char(10) || '| **Bras droit** | -18% | **-15%** au prochain test d’attaque avec une arme |' || char(10) || '| **Bras gauche** | -18% | **-5%** au prochain test (peu importe lequel) |' || char(10) || '| **Jambe droite** | -12% | **-1 vitesse** au prochain tour |' || char(10) || '| **Jambe gauche** | -12% | **-4 initiative** au prochain tour |' || char(10) || '' || char(10) || '## Règles supplémentaires' || char(10) || '' || char(10) || '- **Personnage gaucher :** les effets entre bras droit / bras gauche et jambe droite / jambe gauche sont **inversés**.' || char(10) || '- **Humanoïde par défaut :** ce tableau est pensé pour les créatures humanoïdes.' || char(10) || '- **Adaptation pour monstres :** n’hésite pas à réassigner certaines zones pour coller à l’anatomie de la créature.' || char(10) || '' || char(10) || '  **Exemple :** pour un scorpion, la « tête » correspondait à sa **queue**, et donc le malus/effet s’y appliquaient.' || char(10) || '';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('page guide/attaque-et-defense : titre, résumé et corps (R231 (1))', changes(), 1);

-- 2. Les alias (R231 (1), R184 (2)) : chaque ancien titre reste en alias de sa page ; « Localisation des dégâts » passe à la page Attaquer, qui
--    porte maintenant le tableau. Ordre de la liste `aliases:` : l’ancien titre d’abord.
INSERT INTO alias (page_id, ordre, texte, cle) VALUES ('guide/attaquer-et-se-defendre', 0, 'Attaquer et se défendre', 'attaquer-et-se-defendre');
UPDATE alias SET page_id = 'guide/attaquer-et-se-defendre', ordre = 1 WHERE page_id = 'guide/attaque-et-defense' AND ordre = 0 AND texte = 'Localisation des dégâts';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('alias « Localisation des dégâts » déplacé', changes(), 1);
INSERT INTO alias (page_id, ordre, texte, cle) VALUES ('guide/attaque-et-defense', 0, 'Attaque et Défense', 'attaque-et-defense');

-- 3. Les renvois des autres pages (R231 : « les renvois des autres pages visent la page qui porte maintenant le texte ») : un fragment présent une
--    seule fois dans la valeur d’avant, remplacé dans une seule ligne. guide/guide-pour-mj-maverick (sommaire copié du Doc) ne change pas.
UPDATE page SET corps_md = replace(corps_md, '(voir le tableau « Localisation des dégâts » de {{attaque-et-defense}})',
  '(voir le tableau « Localisation des dégâts » de {{attaquer-et-se-defendre}})')
  WHERE id = 'guide/initiative' AND length(corps_md) - length(replace(corps_md, '(voir le tableau « Localisation des dégâts » de {{attaque-et-defense}})', '')) = length('(voir le tableau « Localisation des dégâts » de {{attaque-et-defense}})');
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('page guide/initiative corps_md : renvoi (R231)', changes(), 1);
