  '(voir le tableau « Localisation des dégâts » de Attaquer)')
  WHERE id = 'guide/initiative' AND length(resume) - length(replace(resume, '(voir le tableau « Localisation des dégâts » de Attaque et Défense)', '')) = length('(voir le tableau « Localisation des dégâts » de Attaque et Défense)');
