-- 3 bis. La défense contre une réussite critique dans deux autres pages (R226 (1), R231 (2)) : la phrase « meilleure » de l’ancienne page devient
--    celle de R231 (2), avec un renvoi à « Se défendre » ; même garde (fragment présent une seule fois, une seule ligne).
UPDATE page SET corps_md = replace(corps_md, 'la cible ne peut bloquer le coup que par une réussite critique meilleure que celle de l’attaquant',
  'seule une réussite critique de la cible peut alors arrêter le coup, entièrement ou en partie (voir {{attaque-et-defense}})')
  WHERE id = 'guide/reussites-echecs-et-critiques' AND length(corps_md) - length(replace(corps_md, 'la cible ne peut bloquer le coup que par une réussite critique meilleure que celle de l’attaquant', '')) = length('la cible ne peut bloquer le coup que par une réussite critique meilleure que celle de l’attaquant');
