  'seule une réussite critique de la cible peut l’arrêter, entièrement ou en partie (voir {{attaque-et-defense}})')
  WHERE id = 'guide/la-magie-en-jeu' AND length(corps_md) - length(replace(corps_md, 'la cible ne peut l’arrêter que par une réussite critique meilleure', '')) = length('la cible ne peut l’arrêter que par une réussite critique meilleure');
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('page guide/la-magie-en-jeu corps_md : critique en défense (R226 (1), R231 (2))', changes(), 1);

-- 4. Les mots-clés de la fiche (R231 (4)) : les 30 compétences et les 6 caractéristiques, couleur caracteristique:<id> (lib/palette-css.mjs, famille
--    caracteristique) ; ni adresse, ni abréviation ; verrou 0 (créés après la 0110 : R219 (5)). La compétence Magie prend l’id magie-competence,
--    « Magie (compétence) » (sinon tools/sheets/magies.py poserait l’étiquette « magie » sur les 15 pages de magie). Parade et Esquive existent :
--    elles gardent id, libellé et définition, et prennent la couleur. Définition d’une compétence : competence.description telle quelle, puis
--    « Caractéristique : {{<carac>|<Nom>}}. » ; Ruse ajoute la phrase de guide/les-attaques-discretes (« Il est nécessaire de réussir un jet de
--    ruse ») ; Vigueur, dont la phrase finit sans point, en reçoit un.
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('arc', 'Arc', 'arc', 'Une compétence liée aux armes qui tirent des flèches. Caractéristique : {{force|Force}}.', NULL, 'caracteristique:force', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('arme-lourde', 'Arme Lourde', 'arme-lourde', 'Une compétence liée à l’utilisation d’arme de catégorie lourde. Caractéristique : {{force|Force}}.', NULL, 'caracteristique:force', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('athletisme', 'Athlétisme', 'athletisme', 'Utilisée lors de tests où la force pure est mise à l''épreuve. (équivalent d’équilibre pour l’agilité) Caractéristique : {{force|Force}}.', NULL, 'caracteristique:force', NULL, 0);
UPDATE mot_cle SET couleur = 'caracteristique:force' WHERE id = 'parade' AND couleur IS NULL;
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle parade : couleur', changes(), 1);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('stabilite', 'Stabilité', 'stabilite', 'Être capable de tenir sa position quand le sol tremble, porter une charge longtemps, etc. (équivalent de réflexe pour l’agilité) Caractéristique : {{force|Force}}.', NULL, 'caracteristique:force', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('calme', 'Calme', 'calme', 'Faire preuve de sang-froid dans les situations dangereuses. Caractéristique : {{volonte|Volonté}}.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('concentration', 'Concentration', 'concentration', 'Permet de rester concentré sur son sort (utilisé par les mages rouge, bleu et vert pour lancer leurs sorts). Caractéristique : {{volonte|Volonté}}.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('fermete', 'Fermeté', 'fermete', 'Mieux résister aux attaques mentales, aux attaques sur le psychique. Caractéristique : {{volonte|Volonté}}.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('survie', 'Survie', 'survie', '"Le corps s’accroche à la vie, telle une sangsue sur une veine" cette compétence est utilisée dans le cas d''un coma. Caractéristique : {{volonte|Volonté}}.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('vigueur', 'Vigueur', 'vigueur', 'Mieux résister aux {{alteration-detat|altérations d''états}} physiques comme le poison, les maladies ou les brûlures. Caractéristique : {{volonte|Volonté}}.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('connaissance', 'Connaissance', 'connaissance', 'Une grande connaissance sur de vastes sujets. Caractéristique : {{intelligence|Intelligence}}.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('magie-competence', 'Magie (compétence)', 'magie-competence', 'La compétence liée aux sortilèges et la capacité à les lancer correctement. Caractéristique : {{intelligence|Intelligence}}.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('medecine', 'Médecine', 'medecine', 'Liée à tous les soins physiques que la magie ne peut soigner. Caractéristique : {{intelligence|Intelligence}}.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('psychologie', 'Psychologie', 'psychologie', 'Permet de comprendre la psychologie de sa cible, déceler le mensonge dans le comportement et les paroles. Caractéristique : {{intelligence|Intelligence}}.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('vie-en-nature', 'Vie en nature', 'vie-en-nature', 'Comprendre la nature, ses bienfaits. Caractéristique : {{intelligence|Intelligence}}.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('arbalete', 'Arbalète', 'arbalete', 'Une compétence liée aux armes qui tirent des carreaux. Caractéristique : {{perception|Perception}}.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('distinction', 'Distinction', 'distinction', 'L''art de voir les choses en profondeur, de sentir, d''écouter, de ressentir. Caractéristique : {{perception|Perception}}.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('observation', 'Observation', 'observation', 'Utiliser sa vue pour bien connaître son environnement en général. Caractéristique : {{perception|Perception}}.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('orientation', 'Orientation', 'orientation', 'Pour bien lire une carte et ne pas se perdre. Caractéristique : {{perception|Perception}}.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('sabotage', 'Sabotage', 'sabotage', 'Créer des pièges, les désarmer ou même les retourner contre les ennemis. Caractéristique : {{perception|Perception}}.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('diplomatie', 'Diplomatie', 'diplomatie', 'Persuader sans violence, ni contrainte. Caractéristique : {{social|Social}}.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('dressage', 'Dressage', 'dressage', 'Liée au dressage d''animaux ou monstres destinés à être des familiers. Caractéristique : {{social|Social}}.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('intimidation', 'Intimidation', 'intimidation', 'Persuader avec violence, sous la contrainte. Caractéristique : {{social|Social}}.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('manipulation', 'Manipulation', 'manipulation', 'L''art du mensonge, du sophisme, du détournement de regard et du déplacement de but. Caractéristique : {{social|Social}}.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('negociation', 'Négociation', 'negociation', 'Liée à l''art de négocier quelque chose. Caractéristique : {{social|Social}}.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('arme-legere', 'Arme Légère', 'arme-legere', 'Une compétence liée à l’utilisation d’arme de catégorie légère. Caractéristique : {{agilite|Agilité}}.', NULL, 'caracteristique:agilite', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('equilibre', 'Équilibre', 'equilibre', 'L''art de garder l’équilibre dans différentes situations. (équivalent d’athlétisme pour la force) Caractéristique : {{agilite|Agilité}}.', NULL, 'caracteristique:agilite', NULL, 0);
UPDATE mot_cle SET couleur = 'caracteristique:agilite' WHERE id = 'esquive' AND couleur IS NULL;
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle esquive : couleur', changes(), 1);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('reflexe', 'Réflexe', 'reflexe', 'Laisser son corps agir de lui-même. (équivalent de stabilité pour la force) Caractéristique : {{agilite|Agilité}}.', NULL, 'caracteristique:agilite', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('ruse', 'Ruse', 'ruse', '"Parfois, ne pas se battre est la meilleure des victoires" Il est nécessaire de réussir un jet de ruse pour une {{attaque-discrete|attaque discrète}}. Caractéristique : {{agilite|Agilité}}.', NULL, 'caracteristique:agilite', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('force', 'Force', 'force', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{arc|Arc}}, {{arme-lourde|Arme Lourde}}, {{athletisme|Athlétisme}}, {{parade|Parade}}, {{stabilite|Stabilité}}). La magie innée {{magie-du-sang|Sang}} ou {{magie-de-la-terre|Terre}} lui donne son +1.', NULL, 'caracteristique:force', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('volonte', 'Volonté', 'volonte', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{calme|Calme}}, {{concentration|Concentration}}, {{fermete|Fermeté}}, {{survie|Survie}}, {{vigueur|Vigueur}}). La magie innée {{magie-du-vide|Vide}} ou {{magie-de-la-necromancie|Nécromancie}} lui donne son +1.', NULL, 'caracteristique:volonte', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('intelligence', 'Intelligence', 'intelligence', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{connaissance|Connaissance}}, {{magie-competence|Magie}}, {{medecine|Médecine}}, {{psychologie|Psychologie}}, {{vie-en-nature|Vie en nature}}). La magie innée {{magie-de-larcane|Arcane}}, {{magie-de-la-corruption|Corruption}}, {{magie-de-lespace-temps|Espace/Temps}} ou {{magie-de-la-glace|Glace}} lui donne son +1.', NULL, 'caracteristique:intelligence', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('perception', 'Perception', 'perception', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{arbalete|Arbalète}}, {{distinction|Distinction}}, {{observation|Observation}}, {{orientation|Orientation}}, {{sabotage|Sabotage}}). La magie innée {{magie-de-la-lumiere|Lumière}} ou {{magie-de-lombre|Ombre}} lui donne son +1.', NULL, 'caracteristique:perception', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('social', 'Social', 'social', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{diplomatie|Diplomatie}}, {{dressage|Dressage}}, {{intimidation|Intimidation}}, {{manipulation|Manipulation}}, {{negociation|Négociation}}). La magie innée {{magie-du-feu|Feu}} ou {{magie-de-leau|Eau}} lui donne son +1.', NULL, 'caracteristique:social', NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('agilite', 'Agilité', 'agilite', 'Une des six {{caracteristiques|caractéristiques}} : elle compte dix fois dans le score de ses cinq compétences ({{arme-legere|Arme Légère}}, {{equilibre|Équilibre}}, {{esquive|Esquive}}, {{reflexe|Réflexe}}, {{ruse|Ruse}}). La magie innée {{magie-du-vent|Vent}} ou {{magie-de-la-foudre|Foudre}} lui donne son +1.', NULL, 'caracteristique:agilite', NULL, 0);

-- 5. Cinq notions (R231 (4), défauts de game-design) : verrou 0 (R219 (5)), sans abréviation ni couleur. SANS ADRESSE : le cahier en donnait une
--    à jet-dattaque, jet-de-defense, ambidextrie et localisation-des-degats (une ancre de la page), mais la règle de la 0110 (R219 (1) : un
--    mot-clé à adresse est verrouillé, épinglée sur l’état d’import par test/serveur-edition-verrou.test.mjs) contredit un mot-clé à adresse non
--    verrouillé écrit par une migration ; repli prévu par le cahier : le mot-clé sans adresse (question à game-design). Les ancres sont posées.
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('jet-dattaque', 'Jet d’attaque', 'jet-dattaque', 'Le D100 de l’attaquant : il doit faire son {{score|score}} ou moins dans la compétence qui sert à l’attaque (celle de l’arme, ou Magie, ou Concentration pour un sort).', NULL, NULL, NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('jet-de-defense', 'Jet de défense', 'jet-de-defense', 'Le D100 de la cible qui pare ou esquive. Pour bloquer entièrement le coup, il doit réussir et donner un résultat égal ou inférieur à celui de l’attaquant ; contre une réussite critique, seule une réussite critique compte.', NULL, NULL, NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('ambidextrie', 'Ambidextrie', 'ambidextrie', 'Une arme de mêlée dans chaque main : −20 % à l’attaque de la main directrice, −40 % à celle de la main secondaire ; le malus est divisé par deux pour la main qui tient une dague et par deux pour la classe Bimane, les deux se cumulant.', NULL, NULL, NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('localisation-des-degats', 'Localisation des dégâts', 'localisation-des-degats', 'Viser la tête, un bras ou une jambe plutôt que le corps : chaque zone a son malus pour toucher et son effet en plus ; le corps n’a ni malus ni effet.', NULL, NULL, NULL, 0);
INSERT INTO mot_cle (id, libelle, libelle_cle, description, abreviation, couleur, url, verrou) VALUES ('meilleur-resultat', 'Meilleur résultat', 'meilleur-resultat', 'Au D100, un meilleur résultat est un résultat plus bas.', NULL, NULL, NULL, 0);

-- 6. Mots-clés existants (R231 (4)) : reussite-critique (R199 (4) : bonus fixes compris), defense-partielle (R231 (2), sans numéro de décision dans le
--    texte affiché : aucune définition n’en porte), et les libellés des mots-clés des deux pages, qui suivent leur titre (verrouillés : seule une
--    migration les change, R218 (4) ; ids et adresses inchangés).
UPDATE mot_cle SET description = replace(description, 'en attaque, les dégâts de base sont doublés', 'en attaque, les dégâts, bonus fixes compris, sont doublés')
  WHERE id = 'reussite-critique' AND length(description) - length(replace(description, 'en attaque, les dégâts de base sont doublés', '')) = length('en attaque, les dégâts de base sont doublés');
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle reussite-critique : définition', changes(), 1);
UPDATE mot_cle SET description = description || ' Contre une réussite critique, seule une défense critique peut être partielle.' WHERE id = 'defense-partielle' AND description = 'Une parade ou une esquive réussie, mais moins bonne que l’attaque. Les dégâts sont divisés par 2. Si c’est une parade partielle faite au bouclier, ses AP et son AM comptent : c’est le seul cas où ils comptent.';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle defense-partielle : définition', changes(), 1);
UPDATE mot_cle SET libelle = 'Attaquer', libelle_cle = 'attaquer' WHERE id = 'attaquer-et-se-defendre' AND libelle = 'Attaquer et se défendre';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle attaquer-et-se-defendre : libellé', changes(), 1);
UPDATE mot_cle SET libelle = 'Se défendre', libelle_cle = 'se-defendre' WHERE id = 'attaque-et-defense' AND libelle = 'Attaque et Défense';
INSERT INTO garde_0112 (quoi, lignes, attendu) VALUES ('mot_cle attaque-et-defense : libellé', changes(), 1);

DROP TABLE garde_0112;
